nexthop_t MemoryImage::walk(int idx, uint64_t cursor) const {
    const ImageNode& n = nodes_[idx];
    if (n.type == 4 || n.type == 5) {
        int best_l = -1;
        uint32_t best_hop = 0;
        for (size_t k = 0; k < n.inlines.size(); ++k) {
            const ImageNode::Pfx& p = n.inlines[k];
            bool m = (p.l == 0) ? true : ((cursor >> (64 - p.l)) == (p.frag >> (64 - p.l)));
            if (m && (int)p.l > best_l) { best_l = p.l; best_hop = p.hop; }
        }
        if (best_l >= 0) return best_hop;
        return (n.bmp == IMAGE_BMP_NULL) ? LPM_INVALID_NH : (nexthop_t)n.bmp;
    }
    const int t = (n.depth - n.origin) / 6;
    const uint64_t chunk = cursor_chunk(cursor, t);
    for (size_t k = 0; k < n.children.size(); ++k)
        if (n.children[k].key == chunk)
            return walk(slots_[n.children[k].stage][n.children[k].cell], cursor);
    if (n.type == 3 && ((n.bulk_bitmap >> chunk) & 1ull)) {
        int rank = __builtin_popcountll(n.bulk_bitmap & ((1ull << chunk) - 1ull));
        uint32_t cell = n.bulk_base + 2u * (uint32_t)rank;
        return walk(slots_[n.bulk_stage][cell], cursor);
    }
    for (int l = 5; l >= 0; --l) {
        int p = (1 << l) + (int)(chunk >> (6 - l));
        if ((n.pattern >> p) & 1ull) {
            int off = __builtin_popcountll(n.pattern & (((uint64_t)1 << p) - 1ull));
            return data_.nexthops[n.ni_base + off];
        }
    }
    return (n.bmp == IMAGE_BMP_NULL) ? LPM_INVALID_NH : (nexthop_t)n.bmp;
}
nexthop_t MemoryImage::lookup(ip6_t ip) const {
    if (!front64_.empty()) {
        int i = find_front(front64_, ip.hi);
        if (i >= 0) return walk(i, ip.lo);
    }
    if (!front16_.empty()) {
        int i = find_front(front16_, ip.hi >> 48);
        if (i >= 0) return walk(i, ip.hi << 16);
    }
    if (root_idx_ >= 0) return walk(root_idx_, ip.hi);
    return LPM_INVALID_NH;
}
